WITH latest_match AS (SELECT s.*, latest.web_event_event_time FROM sessions s LEFT JOIN LATERAL (SELECT c.event_time AS web_event_event_time FROM web_events c WHERE c.session_id = s.id AND c.event_time <= s.started_at ORDER BY c.event_time DESC, c.id DESC LIMIT 1) latest ON TRUE) SELECT id, device, browser, started_at, country, web_event_event_time, CASE WHEN country RLIKE '^(UK|JP)$' THEN 'EXTENDED' WHEN country RLIKE '^(TH|US)$' THEN 'CORE' ELSE 'OTHER_ZONE' END AS country_zone FROM latest_match ORDER BY country DESC NULLS LAST;
